with open('projects/gen-depth-contamination/paper_provenance.yaml') as f:
    data = yaml.safe_load(f)

# Check all claims for string fields where dicts expected
for claim in data.get('claims', []):
    for key, val in claim.items():
        if key == 'evidence' and isinstance(val, str):
            print(f'CLAIM {claim[\"id\"]}: evidence is str: {val}')
        if key == 'decisions':
            if isinstance(val, list):
                for i, d in enumerate(val):
                    if isinstance(d, str):
                        print(f'CLAIM {claim[\"id\"]}: decisions[{i}] is str: {d}')
            elif isinstance(val, str):
                print(f'CLAIM {claim[\"id\"]}: decisions is str: {val}')
        if key == 'location' and isinstance(val, str):
            print(f'CLAIM {claim[\"id\"]}: location is str: {val}')

# Check tables
for tab in data.get('tables', []):
    for cell in tab.get('cells', []):
        if isinstance(cell.get('source'), str):
            print(f'TABLE {tab[\"id\"]}: cell source is str: {cell[\"source\"]}')

# Check figures
for fig in data.get('figures', []):
    if isinstance(fig.get('source'), str):
        print(f'FIGURE {fig[\"id\"]}: source is str: {fig[\"source\"]}')

# Check _completeness
comp = data.get('_completeness', {})
