def check_gets(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            check_gets(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            if isinstance(v, str):
                try:
                    v.get('x')
                except AttributeError:
                    pass  # expected
            elif isinstance(v, dict):
                check_gets(v, f'{path}[{i}]')
