import yaml, sys, traceback

# Try to replicate what check_provenance_completeness does
with open('projects/gen-depth-contamination/paper_provenance.yaml') as f:
    prov = yaml.safe_load(f)

with open('projects/gen-depth-contamination/registry.yaml') as f:
    reg = yaml.safe_load(f)

# Common pattern: iterate claims, look up evidence in registry
claims = prov.get('claims', [])
experiments = reg.get('experiments', {})

for claim in claims:
    evidence = claim.get('evidence', [])
    if isinstance(evidence, list):
        for ev in evidence:
            if isinstance(ev, str):
                exp = experiments.get(ev, {})
                if isinstance(exp, str):
                    print(f'WARNING: experiments[{ev}] is str, not dict')
                elif exp:
                    try:
                        _ = exp.get('status')
                    except:
                        print(f'ERROR on exp {ev}: {traceback.format_exc()}')
            elif isinstance(ev, dict):
                pass
    elif isinstance(evidence, str):
        print(f'CLAIM {claim.get(\"id\")}: evidence is str: {evidence}')

# Also check if the tool iterates _completeness.tier_counts
tc = prov.get('_completeness', {}).get('tier_counts', {})
if isinstance(tc, str):
    print('tier_counts is string!')

print('No string-as-dict issues found in cross-reference check')
